import EventEmitter from "events";
import { Item, Skills } from "type";
import { playerConfig, managerEvents, expConfig } from "./config";
import { inventoryManager } from "./InventoryManager";

class PlayerManager {
  constructor() {
    const rmEquip = inventoryManager.listener("equip", () => {
      this.emitter.emit(managerEvents.UPDATE_SKILL);
    });

    this.rmListeners.push(rmEquip);
  }
  private rmListeners: (() => void)[] = [];
  private emitter = new EventEmitter();

  skillLevels: Skills
   = {
    health: 1,
    attackCoolDown: 1,
    move: 0,
    parry: 0,

    bow: 0,
    meleeWeapon: 1,
    magic: 0,
    lockBreaking: 0,
  };

  skillExp: Skills = {
    health: 0,
    attackCoolDown: 0,
    move: 0,
    parry: 0,

    bow: 0,
    meleeWeapon: 0,
    magic: 0,
    lockBreaking: 0,
  };

  getLevelUpValue = (skill: keyof Skills) => {
    const _100Percent =
      expConfig.volume * expConfig.multiplier * (this.skillLevels[skill] + 1);

    const currentExp = this.skillExp[skill];
    const _1PercentExpValue = _100Percent / 100;
    const currentPercent = currentExp / _1PercentExpValue;

    return {
      _100Percent,
      currentPercent,
      currentExp,
      _1PercentExpValue,
    };
  };

  levelUp = (skill: keyof Skills) => {
    const oldLevel = this.skillLevels[skill];
    this.skillLevels[skill] = oldLevel + 1;
    this.skillExp[skill] = 0;

    this.emitter.emit(managerEvents.UPDATE_SKILL, this.skillLevels);
  };

  private getAllBenefitsFromEquipItems = () => {
    const sumSkillBonus = Object.entries(inventoryManager.equipment).reduce(
      (acm, [type, item]: [string, Item | Item[] | undefined]) => {
        const getSkills = (skills: Skills) => {
          Object.entries(skills).forEach(([skill, value]) => {
            if (skill && value) acm[skill as keyof Skills] += value as number;
          });
        };

        if (item) {
          const isArray = Array.isArray(item);

          if (isArray) {
            item.forEach((i) => {
              //@ts-ignore
              const currentSkills = i?.skills as Skills | undefined;
              if (currentSkills) getSkills(currentSkills);
            });
          } else {
            //@ts-ignore
            const currentSkills = item?.skills as Skills | undefined;
            if (currentSkills) getSkills(currentSkills);
          }
        }

        return acm;
      },
      {
        attackCoolDown: 0,
        bow: 0,
        health: 0,
        lockBreaking: 0,
        magic: 0,
        meleeWeapon: 0,
        move: 0,
        parry: 0,
      } as Skills,
    );

    return sumSkillBonus;
  };

  getSkillValue = (skill: keyof Skills) => {
    const level = this.skillLevels[skill];
    const volume = playerConfig.skillsVolume[skill];
    const mul = playerConfig.skillsMultiplier[skill];
    // inventory mod add here too but later
    const equip = this.getAllBenefitsFromEquipItems();

    switch (skill) {
      case "health":
        return Math.ceil(volume * (mul * level) + equip.health);

      case "attackCoolDown":
        return volume + mul - level * mul + equip.attackCoolDown;
      case "move":
      case "meleeWeapon":
      case "bow":
      case "magic":
      case "parry":
        return volume + level * mul + equip[skill];

      default:
        return level + equip[skill];
    }
  };

  listenChangeValue = (
    skill: keyof Skills,
    callBack: (value: number) => void,
  ) => {
    const updateSkill = () => {
      const currentSkillValue = this.getSkillValue(skill);
      callBack(currentSkillValue);
    };
    this.emitter.addListener(managerEvents.UPDATE_SKILL, updateSkill);

    return () => {
      this.emitter.removeListener(managerEvents.UPDATE_SKILL, updateSkill);
    };
  };

  listenAllSkills = (callBack: (v: Skills) => void) => {
    this.emitter.addListener(managerEvents.UPDATE_SKILL, callBack);

    return () => {
      this.emitter.removeListener(managerEvents.UPDATE_SKILL, callBack);
    };
  };
}

export const playerManager = new PlayerManager();
